import { createOrbitGame, createOrbitView } from './orbit-breach-engine.js';
export function initOrbit(doc, win, makeView = createOrbitView) {
  const $=id=>doc.querySelector('#'+id),canvas=$('arena'),held=new Set(),pointers=new Map(),sessionBests=new Map();
  let model=createOrbitGame(),view,motion=!win.matchMedia('(prefers-reduced-motion: reduce)').matches,dirty=true,last=null,finished=false,best=0;
  try{view=makeView(canvas);}catch{$('game-status').textContent='This game needs Canvas 2D. Try another browser.';$('start').disabled=true;$('game-action').disabled=true;return;}
  const storageKey=()=>`fractal-space-orbit-breach-v1:${model.game.sides}:${model.game.difficulty}`;
  function loadBest(){best=sessionBests.get(storageKey())||0;try{const n=Number(win.localStorage.getItem(storageKey()));if(Number.isFinite(n)&&n>=0&&n<=86400)best=Math.max(best,n);}catch{}}
  function record(){if(model.game.time<=best)return;best=model.game.time;sessionBests.set(storageKey(),best);try{win.localStorage.setItem(storageKey(),String(best));}catch{}}
  function clear(){held.clear();pointers.clear();}
  function ui(){const g=model.game,active=['playing','paused'].includes(g.status);$('sides').disabled=active;$('difficulty').disabled=active;$('pause').disabled=!active;$('pause').textContent=g.status==='paused'?'Resume':'Pause';$('start').textContent=g.status==='ready'?'Start run':'New run';$('motion').textContent='Motion: '+(motion?'On':'Off');$('motion').setAttribute('aria-pressed',String(motion));$('overlay').hidden=g.status==='playing';
    if(g.status==='ready'){$('overlay-title').textContent='Find the gap.';$('overlay-message').textContent='Hold left or right to steer around the core. Stay out of the approaching walls.';$('game-action').textContent='Start run';}
    if(g.status==='paused'){$('overlay-title').textContent='Take a breath.';$('overlay-message').textContent='Your run is paused. Resume when you are ready.';$('game-action').textContent='Resume run';}
    if(g.status==='dead'){$('overlay-title').textContent='Orbit breached.';$('overlay-message').textContent=`${g.time.toFixed(2)} seconds · ${g.score} gaps cleared. Find your rhythm and try again.`;$('game-action').textContent='Try again';}
    $('time').textContent=g.time.toFixed(2)+' s';$('best').textContent=best.toFixed(2)+' s';$('score').textContent=String(g.score);$('stage').textContent=String(g.stage);dirty=true;
  }
  function start(){record();clear();model=createOrbitGame({seed:Math.floor(Math.random()*4294967296),sides:+$('sides').value,difficulty:$('difficulty').value});model.start();finished=false;last=null;loadBest();ui();$('game-status').textContent='Run started. Steer through the gaps.';canvas.focus({preventScroll:true});}
  function pause(){if(model.game.status!=='playing')return;clear();model.pause();record();ui();$('game-status').textContent='Paused. Press P or Resume run to continue.';}
  function resume(){if(model.game.status!=='paused')return;clear();model.resume();last=null;ui();$('game-status').textContent='Run resumed.';canvas.focus({preventScroll:true});}
  function toggle(){if(model.game.status==='playing')pause();else if(model.game.status==='paused')resume();}
  function settings(){if(['playing','paused'].includes(model.game.status))return;clear();model=createOrbitGame({sides:+$('sides').value,difficulty:$('difficulty').value});loadBest();ui();$('game-status').textContent='Ready. Choose an arena, then start your run.';}
  $('start').onclick=start;$('game-action').onclick=()=>model.game.status==='paused'?resume():start();$('pause').onclick=toggle;$('motion').onclick=()=>{motion=!motion;ui();if(model.game.status==='playing')canvas.focus({preventScroll:true});};for(const id of ['sides','difficulty'])$(id).addEventListener('change',settings);
  function direction(){let d=+(held.has('arrowright')||held.has('d'))-+(held.has('arrowleft')||held.has('a'));for(const value of pointers.values())d+=value;return Math.max(-1,Math.min(1,d));}
  function release(e){pointers.delete(e.pointerId);}
  function bind(element,turn){element.onpointerdown=e=>{if(model.game.status!=='playing')return;e.preventDefault();canvas.focus({preventScroll:true});element.setPointerCapture(e.pointerId);pointers.set(e.pointerId,turn(e));};element.onpointerup=release;element.onpointercancel=release;element.onlostpointercapture=release;}
  bind($('left'),()=>-1);bind($('right'),()=>1);for(const [id,d]of [['left',-1],['right',1]]){const key='button:'+id;$(id).addEventListener('keydown',e=>{if([' ','Enter'].includes(e.key)&&model.game.status==='playing'){e.preventDefault();pointers.set(key,d);}});$(id).addEventListener('keyup',e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();pointers.delete(key);}});$(id).addEventListener('blur',()=>pointers.delete(key));}bind(canvas,e=>e.clientX<canvas.getBoundingClientRect().left+canvas.getBoundingClientRect().width/2?-1:1);canvas.onpointermove=e=>{if(pointers.has(e.pointerId))pointers.set(e.pointerId,e.clientX<canvas.getBoundingClientRect().left+canvas.getBoundingClientRect().width/2?-1:1);};canvas.addEventListener('blur',clear);
  win.addEventListener('pointerup',release);win.addEventListener('pointercancel',release);
  win.addEventListener('keydown',e=>{if(e.metaKey||e.ctrlKey||e.altKey||/INPUT|SELECT|BUTTON|TEXTAREA/.test(e.target.tagName))return;const key=e.key.toLowerCase();if(['arrowleft','arrowright','a','d'].includes(key)){e.preventDefault();if(model.game.status==='playing')held.add(key);return;}if(e.repeat)return;if(key===' '||key==='enter'){e.preventDefault();if(['ready','dead'].includes(model.game.status))start();else toggle();}if(key==='p'){e.preventDefault();toggle();}if(key==='r'){e.preventDefault();start();}});
  win.addEventListener('keyup',e=>held.delete(e.key.toLowerCase()));win.addEventListener('blur',pause);win.addEventListener('pagehide',()=>{record();pause();});doc.addEventListener('visibilitychange',()=>{if(doc.hidden)pause();});
  function resize(){const r=canvas.getBoundingClientRect(),ratio=Math.min(win.devicePixelRatio||1,2,1600/Math.max(r.width,r.height));canvas.width=Math.max(1,Math.round(r.width*ratio));canvas.height=Math.max(1,Math.round(r.height*ratio));dirty=true;}
  new win.ResizeObserver(resize).observe(canvas);resize();loadBest();ui();
  $('save').onclick=()=>{view.draw(model.game,{motion});canvas.toBlob(blob=>{if(!blob)return;const url=win.URL.createObjectURL(blob),a=doc.createElement('a');a.download='fractal-space-orbit-breach.png';a.href=url;a.click();win.setTimeout(()=>win.URL.revokeObjectURL(url),1500);});};
  function animate(now){win.requestAnimationFrame(animate);const dt=last===null?0:Math.max(0,Math.min((now-last)/1000,.05));last=now;if(doc.hidden)return;if(model.game.status==='playing'){model.advance(dt,direction());const g=model.game;$('time').textContent=g.time.toFixed(2)+' s';$('score').textContent=String(g.score);$('stage').textContent=String(g.stage);dirty=true;if(g.status==='dead'&&!finished){finished=true;record();clear();ui();$('game-status').textContent=`Run ended at ${g.time.toFixed(2)} seconds. Choose Try again or press R.`;}}if(dirty){view.draw(model.game,{motion});dirty=false;}}
  view.draw(model.game,{motion});dirty=false;win.requestAnimationFrame(animate);return {get model(){return model;},get motion(){return motion;},start,pause,resume,direction};
}
if(typeof document!=='undefined')initOrbit(document,window);
